use filmcraft_project::{Project,ItemId,MediaRef,ParamValue,Keyframe};use filmcraft_project::mask::{Mask,MaskPath,MaskMode,MaskVertex};use filmcraft_geom::Vec2;use filmcraft_time::{Tick,FrameRate};use filmcraft_media::{SharedSource,generators::GeneratorSource};use filmcraft_render::{render_sequence,RenderOptions};use serde_json::{Value,json};use std::sync::Arc;
fn main(){let input:Value=serde_json::from_slice(&std::fs::read(std::env::args().nth(1).unwrap()).unwrap()).unwrap();const T:i64=254016000000;let mut cases=vec![];let defs:Vec<_>=filmcraft_project::effect_defs().iter().filter(|d|matches!(d.id,"opacity"|"invert")).collect();assert_eq!(defs.len(),2);
for definition in defs{for profile in 0..32{for effects_enabled in [false,true]{for enabled in [false,true]{let mut effect=definition.instance();effect.enabled=enabled;
let path=match profile%5{0=>MaskPath::rect(1.25,0.75,6.25,7.25),1=>MaskPath::ellipse(Vec2::new(4.25,3.75),Vec2::new(2.75,3.25)),2=>{let mut p=MaskPath::polygon(&[Vec2::new(-0.5,1.25),Vec2::new(7.25,2.75),Vec2::new(3.25,8.5)]);p.closed=false;p},3=>MaskPath::default(),_=>MaskPath{vertices:vec![MaskVertex::corner(Vec2::new(2.25,3.75))],closed:true}};
let mut mask=Mask::new("clock boundary",path.clone());mask.mode=MaskMode::ALL[profile%7];mask.inverted=profile%2==1;
mask.path.keyframes=vec![Keyframe::new(Tick(0),ParamValue::Path(path)),Keyframe::new(Tick(4*T),ParamValue::Path(MaskPath::ellipse(Vec2::new(3.25,4.5),Vec2::new(3.25,1.75))))];
for(param,lo,hi)in[(&mut mask.feather,0.,2.25),(&mut mask.opacity,35.,85.),(&mut mask.expansion,-1.25,1.5)]{param.keyframes=vec![Keyframe::new(Tick(0),ParamValue::Float(lo)),Keyframe::new(Tick(4*T),ParamValue::Float(hi))];}
effect.masks.push(mask);if definition.id=="opacity"{effect.params.get_mut("opacity").unwrap().value=ParamValue::Float(70.);}
let motion=json!({"effect":"motion","enabled":true,"params":{"scale":{"value":{"Float":73.25}},"rotation":{"value":{"Float":9.25}}}});
let mut authored=vec![motion,json!(effect)];if definition.id!="opacity"{authored.push(json!({"effect":"opacity","enabled":true,"params":{"opacity":{"value":{"Float":70.}}}}));}

let mut doc=input["cases"][profile*8+4]["document"].clone();let media=&mut doc["project"]["items"]["1"]["kind"]["Media"];media["media"]=json!({"Generator":{"Demo":"Plasma"}});media["info"]["video"]["width"]=json!(8);media["info"]["video"]["height"]=json!(8);
let seq=&mut doc["project"]["items"]["6"]["kind"]["Sequence"];seq["settings"]["width"]=json!(16);seq["settings"]["frame_rate"]=match profile%3{0=>json!({"num":24,"den":1}),1=>json!({"num":30000,"den":1001}),_=>json!({"num":60,"den":1})};seq["settings"]["height"]=json!(8);seq["caption_tracks"]=json!([]);let mut track=seq["video_tracks"][0].clone();track["enabled"]=json!(true);track["transitions"]=json!([]);let mut clip=track["items"][0].clone();clip["item"]=json!(1);if profile%2==1{clip["start"]=json!(T/4);}clip["effects"]=json!(authored);track["items"]=json!([clip]);seq["video_tracks"]=json!([track]);let p:Project=serde_json::from_value(doc["project"].clone()).unwrap();let provider=|id:ItemId|{let(_,media,_)=p.resolve_media(id)?;let MediaRef::Generator(generator)=&media.media else{return None};Some(Arc::new(GeneratorSource::new(generator.clone(),8,8,FrameRate::new(24,1),Tick(100*T)))as SharedSource)};
for at in [2*T,9*T/4]{for scale in [1.,0.5]{let out=render_sequence(&p,ItemId(6),Tick(at),RenderOptions{scale,effects:effects_enabled,working_output:true,..Default::default()},&provider);cases.push(json!({"document":doc,"sequence":6,"at":at,"effect":definition.id,"profile":profile,"effects_enabled":effects_enabled,"enabled":enabled,"scale":scale,"width":out.w,"height":out.h,"bits":out.px.iter().map(|v|v.to_bits()).collect::<Vec<_>>()}));}}
}}}}
println!("{}",json!({"commit":"5231852443363f001c3f6b396dd9b1e6461ae2be","definitions":2,"cases":cases}));}
